    let entry = WorkModule::get_int(module, *FIGHTER_INSTANCE_WORK_ID_INT_ENTRY_ID);
    if !(0..8).contains(&entry) { return; }
    let mut hook = VAULT_HOOK.lock().unwrap();
    if !hook.recording {
