static SERIAL: AtomicU64 = AtomicU64::new(1);
static REQUESTED: AtomicU64 = AtomicU64::new(0);
static CONSUMED: AtomicU64 = AtomicU64::new(0);
static STOP_QUEUED: AtomicBool = AtomicBool::new(false);
